  const evidence=(x:any)=>x.evidence?`${x.evidence.type==='scout'?'🔎 '+T('Máy So Giá','Price Checker'):x.evidence.type==='confirm'?'👍 '+T('“Tôi cũng thấy giá này”','“I saw this price too”'):x.evidence.type==='receipt'?'🧾 '+T('Hóa đơn','Receipt')+(x.evidence.generic?' · '+T('dòng chưa rõ món, gia đình tự đặt tên','unknown line, item named by the family'):''):'📸 '+T('Ảnh kệ giá','Shelf photo')}${x.evidence.type==='shelf-photo'?` · OCR ${money(x.evidence.ocrPrice)} ${x.evidence.ocrMatches?chip('green',T('khớp','match')):chip('amber',T('không khớp','mismatch'))}`:''}${x.evidence.hash?` · <code>${esc(x.evidence.hash)}…</code>`:''}${x.capturedAt?` · <span data-captured="${esc(x.capturedAt)}">${esc(T('chụp/đọc lúc ','captured ')+new Date(x.capturedAt).toLocaleString(lang==='en'?'en-AU':'vi-VN',{weekday:'short',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}))}</span>`:''}`:'—';
